describe('Search Filter Results Count', () => {
  beforeEach(() => {
    cy.visit('/search');
    cy.get('[data-testid="search-input"]').should('be.visible');
  });

  it('should display result counts for each filter option', () => {
    cy.get('[data-testid="search-input"]').type('laptop');
    cy.get('[data-testid="search-button"]').click();

    cy.get('[data-testid="filter-panel"]').should('be.visible');

    cy.get('[data-testid="filter-category"]').each(($filter) => {
      cy.wrap($filter).within(() => {
        cy.get('[data-testid="filter-label"]').should('be.visible');
        cy.get('[data-testid="filter-count"]').should('be.visible');
        cy.get('[data-testid="filter-count"]').should('contain', /^\d+$/);
      });
    });

    cy.get('[data-testid="filter-count"]').first().then(($count) => {
      const initialCount = parseInt($count.text());
      expect(initialCount).to.be.greaterThan(0);
    });
  });

  it('should update result counts when applying filters', () => {
    cy.get('[data-testid="search-input"]').type('phone');
    cy.get('[data-testid="search-button"]').click();

    cy.get('[data-testid="filter-option"]').first().then(($option) => {
      cy.wrap($option).find('[data-testid="filter-count"]').invoke('text').as('initialCount');
    });

    cy.get('[data-testid="filter-option"]').first().click();

    cy.get('[data-testid="results-count"]').should('be.visible');
    cy.get('[data-testid="results-count"]').invoke('text').then((text) => {
      const resultCount = parseInt(text.match(/\d+/)[0]);
      expect(resultCount).to.be.greaterThan(0);
    });

    cy.get('[data-testid="filter-option"]').first().find('[data-testid="filter-count"]').invoke('text').then((updatedCount) => {
      cy.get('@initialCount').then((initialCount) => {
        expect(parseInt(updatedCount)).to.be.lessThanOrEqual(parseInt(initialCount));
      });
    });
  });

  it('should handle edge case with zero results for a filter', () => {
    cy.get('[data-testid="search-input"]').type('nonexistentproduct12345');
    cy.get('[data-testid="search-button"]').click();

    cy.get('[data-testid="filter-option"]').each(($filter) => {
      cy.wrap($filter).find('[data-testid="filter-count"]').invoke('text').then((count) => {
        const numCount = parseInt(count);
        expect(numCount).to.equal(0);
      });
    });

    cy.get('[data-testid="no-results-message"]').should('be.visible');
  });

  it('should display accurate counts across multiple filter categories', () => {
    cy.get('[data-testid="search-input"]').type('camera');
    cy.get('[data-testid="search-button"]').click();

    const filterCategories = ['brand', 'price', 'rating', 'availability'];

    filterCategories.forEach((category) => {
      cy.get(`[data-testid="filter-category-${category}"]`).within(() => {
        cy.get('[data-testid="filter-option"]').each(($option) => {
          cy.wrap($option).find('[data-testid="filter-count"]').should('exist');
          cy.wrap($option).find('[data-testid="filter-count"]').invoke('text').then((count) => {
            expect(count).to.match(/^\d+$/);
          });
        });
      });
    });
  });
});
